'use strict';

var xorshift128plus = require( './../lib' );

var rng = xorshift128plus();
console.log( '\nDefault Generator:' );
var i;
for ( i = 0; i < 10; i++ ) {
	console.log( rng() );
}

// Create a new pseudorandom number generator...
var rand1 = xorshift128plus({
	'seed': 1234
});
var rand2 = xorshift128plus({
	'seed': 1234
});
console.log( '\nSame seed (reproducible):' );
for ( i = 0; i < 5; i++ ) {
	console.log( rand1(), rand2() );
}

// Create another pseudorandom number generator using a previous seed...
var rand3 = xorshift128plus({
	'seed': 111
});
var rand4 = xorshift128plus({
	'seed': 999
});
console.log( '\nDifferent seeds (independent);' );
for ( i = 0; i < 5; i++ ) {
	console.log( rand3(), rand4() );
}
